#include <format>
#include <iostream>
#include <memory>
#include <span>
#include <string>
#include <utility>
#include <vector>

struct Node {
  int key = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

// The link that owns the node holding key, or the empty link where such a node would go.
[[nodiscard]] std::unique_ptr<Node>* find_link(std::unique_ptr<Node>* link, int key) {
  while (*link != nullptr && (*link)->key != key)
    link = key < (*link)->key ? &(*link)->left : &(*link)->right;
  return link;
}

bool insert(std::unique_ptr<Node>& root, int key) {
  std::unique_ptr<Node>* link = find_link(&root, key);
  if (*link != nullptr) return false;  // the key is already in the tree
  *link = std::make_unique<Node>(key, nullptr, nullptr);
  return true;
}

[[nodiscard]] bool contains(const Node* n, int key) {
  while (n != nullptr && n->key != key) n = key < n->key ? n->left.get() : n->right.get();
  return n != nullptr;
}

bool erase(std::unique_ptr<Node>& root, int key) {
  std::unique_ptr<Node>* link = find_link(&root, key);
  if (*link == nullptr) return false;
  Node& victim = **link;
  if (victim.left == nullptr || victim.right == nullptr) {
    // No child, or one child: the child, or nothing, takes the node's place.
    std::unique_ptr<Node> child = std::move(victim.left != nullptr ? victim.left : victim.right);
    *link = std::move(child);  // the node dies here with both links already empty
    return true;
  }
  // Two children: the smallest key of the right subtree goes up, and its node comes out.
  std::unique_ptr<Node>* successor = &victim.right;
  while ((*successor)->left != nullptr) successor = &(*successor)->left;
  victim.key = (*successor)->key;
  std::unique_ptr<Node> rest = std::move((*successor)->right);  // the successor has no left child
  *successor = std::move(rest);
  return true;
}

// In-order, iteratively, which is ascending order for a binary search tree.
[[nodiscard]] std::vector<int> sorted(const Node* root) {
  std::vector<int> out;
  std::vector<const Node*> pending;
  const Node* current = root;
  while (current != nullptr || !pending.empty()) {
    while (current != nullptr) {
      pending.push_back(current);
      current = current->left.get();
    }
    current = pending.back();
    pending.pop_back();
    out.push_back(current->key);
    current = current->right.get();
  }
  return out;
}

[[nodiscard]] std::string shape(const Node* n) {  // pre-order, with . for a missing child
  if (n == nullptr) return ".";
  if (n->left == nullptr && n->right == nullptr) return std::format("{}", n->key);
  return std::format("{}({} {})", n->key, shape(n->left.get()), shape(n->right.get()));
}

[[nodiscard]] std::string show(std::span<const int> values) {
  std::string out;
  for (const int v : values) out += std::format("{}{}", out.empty() ? "" : " ", v);
  return out;
}

int main() {
  std::unique_ptr<Node> root;
  for (const int key : {5, 3, 8, 2, 4, 9, 1}) insert(root, key);
  std::cout << std::format("built      {}\n", shape(root.get()));
  std::cout << std::format("in-order   {}\n", show(sorted(root.get())));
  std::cout << std::format("insert 4 again: {}, contains 4: {}, contains 6: {}\n", insert(root, 4),
                           contains(root.get(), 4), contains(root.get(), 6));
  erase(root, 1);
  std::cout << std::format("erase 1    {}   no children\n", shape(root.get()));
  erase(root, 8);
  std::cout << std::format("erase 8    {}   one child\n", shape(root.get()));
  erase(root, 5);
  std::cout << std::format("erase 5    {}   two children\n", shape(root.get()));
  std::cout << std::format("in-order   {}, erase 7: {}\n", show(sorted(root.get())), erase(root, 7));
}

#include <algorithm>
#include <cstddef>
