#include <format>
#include <iostream>
#include <memory>
#include <numeric>
#include <random>
#include <span>
#include <string_view>
#include <utility>
#include <vector>

struct Node {
  int key = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

void insert(std::unique_ptr<Node>& root, int key, std::int64_t& comparisons) {
  std::unique_ptr<Node>* link = &root;
  while (*link != nullptr) {
    ++comparisons;
    link = key < (*link)->key ? &(*link)->left : &(*link)->right;
  }
  *link = std::make_unique<Node>(key, nullptr, nullptr);
}

[[nodiscard]] bool contains(const Node* n, int key, std::int64_t& comparisons) {
  while (n != nullptr && n->key != key) {
    ++comparisons;
    n = key < n->key ? n->left.get() : n->right.get();
  }
  return n != nullptr;
}

[[nodiscard]] std::ptrdiff_t height(const Node* root) {  // in nodes, iteratively
  struct Reached {
    const Node* node = nullptr;
    std::ptrdiff_t depth = 0;
  };
  std::ptrdiff_t deepest = 0;
  std::vector<Reached> pending;
  if (root != nullptr) pending.push_back({.node = root, .depth = 1});
  while (!pending.empty()) {
    const Reached here = pending.back();
    pending.pop_back();
    deepest = std::max(deepest, here.depth);
    if (here.node->left) pending.push_back({.node = here.node->left.get(), .depth = here.depth + 1});
    if (here.node->right) pending.push_back({.node = here.node->right.get(), .depth = here.depth + 1});
  }
  return deepest;
}

void row(std::string_view order, std::span<const int> keys) {
  std::unique_ptr<Node> root;
  std::int64_t building = 0;
  for (const int key : keys) insert(root, key, building);
  std::int64_t looking = 0;
  bool all_found = true;
  for (const int key : keys) all_found = contains(root.get(), key, looking) && all_found;
  const double average = static_cast<double>(looking) / static_cast<double>(std::ssize(keys));
  std::cout << std::format("{:<22}{:>8}{:>14}{:>14}{:>10.1f}   {}\n", order, height(root.get()), building, looking,
                           average, all_found);
}

int main() {
  constexpr int n = 4096;
  std::vector<int> keys(n);
  std::iota(keys.begin(), keys.end(), 0);
  std::cout << std::format("{:<22}{:>8}{:>14}{:>14}{:>10}   {}\n", "insertion order", "height", "to build",
                           "to look up", "per key", "all found");
  row("0 to 4095 in order", keys);
  std::mt19937 gen{42};
  std::ranges::shuffle(keys, gen);
  row("the same, shuffled", keys);
}

#include <format>
#include <iostream>
#include <limits>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

struct Node {
  int key = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int key, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(key, std::move(left), std::move(right));
}

// The first key that is not strictly greater than the key before it in in-order, or no value
// when the whole tree is a binary search tree with distinct keys.
[[nodiscard]] std::optional<int> first_out_of_order(const Node* root) {
  std::vector<const Node*> pending;
  const Node* current = root;
  std::optional<int> previous;  // the key visited before this one, if any
  while (current != nullptr || !pending.empty()) {
    while (current != nullptr) {
      pending.push_back(current);
      current = current->left.get();
    }
    current = pending.back();
    pending.pop_back();
    if (previous && *previous >= current->key) return current->key;  // stop at the first break
    previous = current->key;
    current = current->right.get();
  }
  return std::nullopt;
}

void report(std::string_view name, const Node* root) {
  const std::optional<int> bad = first_out_of_order(root);
  std::cout << std::format("{:<34}{}\n", name, bad ? std::format("breaks at {}", *bad) : "a valid BST");
}

int main() {
  const std::unique_ptr<Node> good = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  report("the tree from the cold check", good.get());
  const std::unique_ptr<Node> grandchild = node(5, node(3), node(8, node(4), node(9)));
  report("4 under the right child 8", grandchild.get());
  const std::unique_ptr<Node> duplicate = node(5, node(5), node(8));
  report("a second 5 on the left", duplicate.get());
  constexpr int lowest = std::numeric_limits<int>::min();
  constexpr int highest = std::numeric_limits<int>::max();
  const std::unique_ptr<Node> extremes = node(0, node(lowest), node(highest));
  report("the two extreme int values", extremes.get());
  const std::unique_ptr<Node> only_min = node(lowest);
  report("a single node holding the lowest", only_min.get());
  report("the empty tree", nullptr);
}

#include <format>
#include <iostream>
#include <memory>
#include <optional>
#include <string>
#include <utility>
#include <vector>

struct Node {
  int key = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int key, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(key, std::move(left), std::move(right));
}

[[nodiscard]] bool contains(const Node* n, int key) {
  while (n != nullptr && n->key != key) n = key < n->key ? n->left.get() : n->right.get();
  return n != nullptr;
}

// In a BST: walk down while both keys are on the same side. O(h) time, O(1) space.
[[nodiscard]] std::optional<int> lca_bst(const Node* root, int a, int b) {
  if (!contains(root, a) || !contains(root, b)) return std::nullopt;
  const Node* n = root;
  while (n != nullptr) {
    if (a < n->key && b < n->key) n = n->left.get();
    else if (a > n->key && b > n->key) n = n->right.get();
    else return n->key;  // the keys part here, or one of them is this node
  }
  return std::nullopt;
}

[[nodiscard]] bool holds(const Node* n, int key) {  // any order, so the whole subtree is searched
  if (n == nullptr) return false;
  return n->key == key || holds(n->left.get(), key) || holds(n->right.get(), key);
}

[[nodiscard]] const Node* lca_node(const Node* n, int a, int b) {
  if (n == nullptr || n->key == a || n->key == b) return n;
  const Node* left = lca_node(n->left.get(), a, b);
  const Node* right = lca_node(n->right.get(), a, b);
  if (left != nullptr && right != nullptr) return n;  // the keys are on different sides: this is the meeting point
  return left != nullptr ? left : right;
}

// In any binary tree with distinct keys. O(n) time, O(h) stack.
[[nodiscard]] std::optional<int> lca_any(const Node* root, int a, int b) {
  if (!holds(root, a) || !holds(root, b)) return std::nullopt;
  const Node* found = lca_node(root, a, b);
  return found != nullptr ? std::optional<int>{found->key} : std::nullopt;
}

[[nodiscard]] std::string text(std::optional<int> value) {
  return value ? std::format("{}", *value) : "none";
}

int main() {
  const std::unique_ptr<Node> tree = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  const std::vector<std::pair<int, int>> pairs{{1, 4}, {2, 4}, {1, 9}, {3, 3}, {3, 4}, {5, 9}, {4, 7}};
  for (const auto& [a, b] : pairs)
    std::cout << std::format("{} and {}: bst {:<5} any order {}\n", a, b, text(lca_bst(tree.get(), a, b)),
                             text(lca_any(tree.get(), a, b)));
  const std::unique_ptr<Node> unordered = node(5, node(9, node(1), node(4)), node(3, node(8), nullptr));
  std::cout << std::format("unordered tree, 1 and 4: {}\n", text(lca_any(unordered.get(), 1, 4)));
  std::cout << std::format("unordered tree, 1 and 8: {}\n", text(lca_any(unordered.get(), 1, 8)));
  std::cout << std::format("empty tree, 1 and 2: {} and {}\n", text(lca_bst(nullptr, 1, 2)),
                           text(lca_any(nullptr, 1, 2)));
}

#include <format>
#include <iostream>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

struct Node {
  int key = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int key, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(key, std::move(left), std::move(right));
}

// The check people write first: every child is on the correct side of its own parent.
[[nodiscard]] bool parent_only(const Node* n) {
  if (n == nullptr) return true;
  if (n->left != nullptr && n->left->key >= n->key) return false;
  if (n->right != nullptr && n->right->key <= n->key) return false;
  return parent_only(n->left.get()) && parent_only(n->right.get());
}

// The whole subtree has to fit between the bounds its ancestors set.
[[nodiscard]] bool in_range(const Node* n, std::optional<int> low, std::optional<int> high) {
  if (n == nullptr) return true;
  if (low && n->key <= *low) return false;
  if (high && n->key >= *high) return false;
  return in_range(n->left.get(), low, n->key) && in_range(n->right.get(), n->key, high);
}

// The search a BST promises: one comparison per level, never looking at the other side.
[[nodiscard]] bool contains(const Node* n, int key) {
  while (n != nullptr && n->key != key) n = key < n->key ? n->left.get() : n->right.get();
  return n != nullptr;
}

enum class Ties { none, left, right };

// Equal keys are allowed only on the side `ties` names.
[[nodiscard]] bool fits(const Node* n, std::optional<int> low, std::optional<int> high, Ties ties) {
  if (n == nullptr) return true;
  if (low && (ties == Ties::right ? n->key < *low : n->key <= *low)) return false;
  if (high && (ties == Ties::left ? n->key > *high : n->key >= *high)) return false;
  return fits(n->left.get(), low, n->key, ties) && fits(n->right.get(), n->key, high, ties);
}

[[nodiscard]] std::string verdicts(const Node* root) {
  return std::format("{:<7}{:<7}{}", fits(root, std::nullopt, std::nullopt, Ties::none) ? "yes" : "no",
                     fits(root, std::nullopt, std::nullopt, Ties::left) ? "yes" : "no",
                     fits(root, std::nullopt, std::nullopt, Ties::right) ? "yes" : "no");
}

int main() {
  const std::unique_ptr<Node> broken = node(5, node(3), node(8, node(4), node(9)));
  std::cout << std::format("4 sits under 8, which sits right of 5\n");
  std::cout << std::format("  every child fits its parent: {}\n", parent_only(broken.get()));
  std::cout << std::format("  every subtree fits its bounds: {}\n", in_range(broken.get(), std::nullopt, std::nullopt));
  std::cout << std::format("  a BST search finds 4: {}, finds 9: {}\n", contains(broken.get(), 4),
                           contains(broken.get(), 9));

  const std::unique_ptr<Node> ties_right = node(5, node(3), node(5, nullptr, node(8)));
  const std::unique_ptr<Node> ties_left = node(5, node(5, node(3), nullptr), node(8));
  std::cout << std::format("\n{:<28}{:<7}{:<7}{}\n", "equal keys", "strict", "left", "right");
  std::cout << std::format("{:<28}{}\n", "the second 5 on the right", verdicts(ties_right.get()));
  std::cout << std::format("{:<28}{}\n", "the second 5 on the left", verdicts(ties_left.get()));
}
